tasks.command:
powershell -NoProfile -ExecutionPolicy Bypass -Command "(Get-Content src/webparts/myCalendars/components/MyCalendars.tsx) -replace 'public componentDidUpdate\(prevProps: IMyCalendarsProps\): void \{\s*if \(prevProps.settings.sources \!== this.props.settings.sources\) \{\s*void this.loadAppointments\(\);\s*\}\s*\}', 'public componentDidUpdate(prevProps: IMyCalendarsProps): void {
    try {
      const prevJson = JSON.stringify(prevProps.settings);
      const currJson = JSON.stringify(this.props.settings);
      if (prevJson !== currJson) {
        void this.loadAppointments();
      }
    } catch {
      // Fallback to sources change detection
      if (prevProps.settings.sources !== this.props.settings.sources) {
        void this.loadAppointments();
      }
    }
  }' | Set-Content src/webparts/myCalendars/components/MyCalendars.tsx"
